from collections import deque

def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if g[r][c] != 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and g[ny][nx] == 0 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            comps.append(comp)
    if comps:
        largest = max(comps, key=len)
        smallest = min(comps, key=len)
        for r, c in largest:
            g[r][c] = 8
        for r, c in smallest:
            g[r][c] = 7
    return g
